  "    d.append(body); d.append(contentsOf: u32(11 + body.count)); return d",
  "  }",
  "  func write(_ fd: CMFormatDescription, _ avcc: Data, key: Bool, ms: Int) {",
  "    lock.lock(); defer { lock.unlock() }",
  "    var out = Data()",
  "    if !head { out.append(Data(\"FLV\".utf8) + Data([1, 1] + u32(9) + u32(0))); head = true }",
  "    var count = 0, nalLen: Int32 = 0",
  "    CMVideoFormatDescriptionGetH264ParameterSetAtIndex(fd, parameterSetIndex: 0, parameterSetPointerOut: nil, parameterSetSizeOut: nil, parameterSetCountOut: &count, nalUnitHeaderLengthOut: &nalLen)",
