  "      for x in sps { rec.append(contentsOf: [UInt8(x.count >> 8), UInt8(x.count & 255)]); rec.append(x) }",
  "      rec.append(UInt8(pps.count))",
  "      for x in pps { rec.append(contentsOf: [UInt8(x.count >> 8), UInt8(x.count & 255)]); rec.append(x) }",
